	/** Installs one binding-owned exact domain and records its construction metadata for runtime plans. */
	public static void installExactDomain(int domainId, String label, String producer, long[] unsignedSortedValues,
			int offset, int length) {
		long started = System.nanoTime();
		LmdbNativeSipFilter.Domain domain;
		if (unsignedSortedValues == null) {
			domain = LmdbNativeSipFilter.ALL;
		} else if (length <= 0) {
			domain = LmdbNativeSipFilter.EMPTY;
		} else {
			try {
				domain = LmdbNativeSipFilter.borrowedSorted(unsignedSortedValues, offset, length);
			} catch (IllegalArgumentException unsorted) {
				// VALUES and folded IN domains preserve query order, which need not be unsigned order. Build a
				// tiny exact set once at bind time rather than either corrupting membership or forcing every
				// generated guard through a linear scan. Store-backed key domains normally take the borrowed path.
				LmdbNativeSipFilter.Builder builder = LmdbNativeSipFilter.builder(length, (long) length * Long.BYTES,
						false);
				for (int i = 0; i < length; i++) {
					builder.accept(unsignedSortedValues[offset + i]);
				}
				domain = builder.build();
			}
		}
		long elapsed = System.nanoTime() - started;
		// The array belongs to KernelContext/its immutable adjacency. The query owns only the tiny domain descriptor.
		LmdbFusedSipFactorizedRuntime.current().installDomain(domainId, label, producer, domain, elapsed, 0L);
	}

