	private static final class SharedFilterFeedback {
		private final int preferredStage;
		private final double score;
		private final int observations;

		SharedFilterFeedback(int stage, long tested, long accepted, long elapsed, long avoided, int observations) {
			this.preferredStage = stage;
			this.score = score(tested, accepted, elapsed, avoided);
			this.observations = observations;
		}

		SharedFilterFeedback update(int stage, long tested, long accepted, long elapsed, long avoided) {
			double candidate = score(tested, accepted, elapsed, avoided);
			int selectedStage = preferredStage;
			double selectedScore = score;
			// Require a 12.5% benefit before changing generated placement; this avoids plan flapping.
			if (candidate > score * 1.125) {
				selectedStage = stage;
				selectedScore = candidate;
			} else {
				selectedScore = score * 0.8 + candidate * 0.2;
			}
			return new SharedFilterFeedback(selectedStage, selectedScore, observations + 1);
		}

		private SharedFilterFeedback(int preferredStage, double score, int observations) {
			this.preferredStage = preferredStage;
			this.score = score;
			this.observations = observations;
		}

		private static double score(long tested, long accepted, long elapsed, long avoided) {
			double rejected = tested - accepted;
			return (rejected + Math.max(0, avoided)) / Math.max(1.0, elapsed);
		}
	}
